{
    return thing.Get() && !thing->IsDead();
}

void CTCTavernGame::SetState(ETavernGameStates state)
{
    if (g_bTavernGameQuitRequested) {
        g_bTavernGameQuitRequested = false;
        state = (ETavernGameStates)47;
    }
